    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        String desktopPath = javax.swing.filechooser.FileSystemView.getFileSystemView().getHomeDirectory().getAbsolutePath();
        // Cria o JFileChooser e define a área de Trabalho como diretório inicial
        JFileChooser ch = new JFileChooser();
        ch.setCurrentDirectory(new File(desktopPath));
        ch.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
        int se = ch.showSaveDialog(null);
        if (se == JFileChooser.APPROVE_OPTION) {
            // Captura o caminho selecionado pelo usuário
            String caminho = ch.getSelectedFile().getAbsolutePath();
            jTextFieldCaminho.setText(caminho);
        }
    }//GEN-LAST:event_jButton1ActionPerformed

    @SuppressWarnings({"deprecation", "deprecation"})
    private void jButtonExportarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonExportarActionPerformed
        String caminho = jTextFieldCaminho.getText();
        if (caminho.trim().isEmpty()) {
            JOptionPane.showMessageDialog(this, "Por favor, selecione um diretório de destino para o backup.");
            return;
        }
        String diretorioAtual = System.getProperty("user.dir");
        String origemSQLite = diretorioAtual + File.separator + "jfinslt.db";
        String timeStamp = new SimpleDateFormat("yyyyMMdd_HHmmss").format(new Date());
        String nomeArquivoBackup = "bkpSQLite-" + timeStamp + ".db";
        String destinoBackup = caminho + File.separator + nomeArquivoBackup;
        if (backupSQLite(origemSQLite, destinoBackup)) {
            JOptionPane.showMessageDialog(this, "Backup realizado com sucesso: " + nomeArquivoBackup);
        } else {
            JOptionPane.showMessageDialog(this, "Erro ao realizar o backup.");
        }
    }//GEN-LAST:event_jButtonExportarActionPerformed

